// Writes the Better Auth core schema for Postgres (migrations-pg/0001), generated by Better Auth
// against an empty database so the output is the full CREATE set.
// usage: PG_URL=<empty local database> node scripts/gen-auth-migration-pg.mjs <out.sql>
import { writeFileSync } from "node:fs";
import pg from "pg";
import { getMigrations } from "better-auth/db/migration";

const out = process.argv[2];
const url = process.env.PG_URL;
if (!out || !url) throw new Error("usage: PG_URL=<url> gen-auth-migration-pg.mjs <out.sql>");

const pool = new pg.Pool({ connectionString: url });
try {
  const { compileMigrations } = await getMigrations({
    database: pool,
    emailAndPassword: { enabled: true },
    socialProviders: { google: { clientId: "x", clientSecret: "x" } },
    rateLimit: { enabled: true, storage: "database" },
  });
  const sql = await compileMigrations();
  if (!sql.trim()) throw new Error("no SQL produced; is the database empty?");
  writeFileSync(out, sql.endsWith("\n") ? sql : sql + "\n");
  console.log(`wrote ${out}`);
} finally {
  await pool.end();
}
